import sys

if len(sys.argv) < 4:
    print(f"Uso: python {sys.argv[0]} <arquivo> <linha_inicio> <linha_fim>")
    sys.exit(1)

nome_arquivo = sys.argv[1]
inicio = int(sys.argv[2])
fim = int(sys.argv[3])

try:
    with open(nome_arquivo, "r", encoding="utf-8") as f:
        for num_linha, linha in enumerate(f, start=1):
            if inicio <= num_linha <= fim:
                print(f"{num_linha:3d}: {linha}", end="")
            elif num_linha > fim:
                break
except FileNotFoundError:
    print(f"Arquivo '{nome_arquivo}' inexistente.")

def fundir_arquivos(caminho1, caminho2, caminho_saida):
    with open(caminho1, "r", encoding="utf-8") as f1, \
         open(caminho2, "r", encoding="utf-8") as f2, \
         open(caminho_saida, "w", encoding="utf-8") as f_out:

        linhas1 = f1.readlines()
        linhas2 = f2.readlines()

        max_linhas = max(len(linhas1), len(linhas2))
        for i in range(max_linhas):
            if i < len(linhas1):
                f_out.write(linhas1[i])
            if i < len(linhas2):
                f_out.write(linhas2[i])

print("Fusão alternada concluída com sucesso!")

