def paginar_arquivo(caminho, linhas_por_pagina=60):
    try:
        with open(caminho, "r", encoding="utf-8") as f:
            pagina = 1
            contador = 0
            for linha in f:
                print(linha, end="")
                contador += 1
                if contador == linhas_por_pagina:
                    print(f"\n{'=' * 20} Página {pagina} {'=' * 20}")
                    input("Pressione ENTER para a próxima página...")
                    contador = 0
                    pagina += 1
            if contador > 0:
                print(f"\n{'=' * 20} Página {pagina} (Fim) {'=' * 20}")
    except FileNotFoundError:
        print("Arquivo não encontrado.")

import os

def auditoria_espaco(caminho_inicial):
    print(f"{'Diretório':<50} {'Tamanho (MB)':>12}")
    print("-" * 64)

    for raiz, _, arquivos in os.walk(caminho_inicial):
        soma_dir = 0
        for arq in arquivos:
            caminho_completo = os.path.join(raiz, arq)
            try:
                if os.path.isfile(caminho_completo):
                    soma_dir += os.path.getsize(caminho_completo)
            except OSError:
                pass
        mb = soma_dir / (1024 * 1024)
        print(f"{raiz:<50} {mb:>12.3f} MB")

auditoria_espaco(".")
